CREATE TABLE qhr_recruitment_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,department_id uuid,position_id uuid,quantity int NOT NULL DEFAULT 1,reason text,jd_ref uuid,status varchar(40) NOT NULL DEFAULT 'draft',workflow_instance_id uuid,rejection_reason text,created_by uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_recruitment_requests_org_idx ON qhr_recruitment_requests(org_id,status);
CREATE TABLE qhr_recruitment_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,period_type varchar(20) NOT NULL,period varchar(40) NOT NULL,items jsonb NOT NULL DEFAULT '[]',status varchar(40) NOT NULL DEFAULT 'draft',workflow_instance_id uuid,approved_by uuid,decision_no varchar(80),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_recruitment_plans_org_idx ON qhr_recruitment_plans(org_id,status);
CREATE TABLE qhr_job_descriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,title varchar(200) NOT NULL,position_level varchar(40) NOT NULL DEFAULT 'staff',requires_technical_test boolean NOT NULL DEFAULT false,jd_content text,qualification_standard text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_job_descriptions_org_idx ON qhr_job_descriptions(org_id,title);
CREATE TABLE qhr_job_postings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,recruitment_plan_id uuid,job_description_id uuid,position_id uuid,position_level varchar(40) NOT NULL DEFAULT 'staff',requires_technical_test boolean NOT NULL DEFAULT false,channels jsonb NOT NULL DEFAULT '[]',published_at timestamptz,status varchar(40) NOT NULL DEFAULT 'draft',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_job_postings_org_idx ON qhr_job_postings(org_id,status);
CREATE TABLE qhr_candidates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,full_name varchar(200) NOT NULL,contact jsonb NOT NULL DEFAULT '{}',source_channel varchar(80),cv_file uuid,self_declaration jsonb,hired_employee_id uuid,status varchar(40) NOT NULL DEFAULT 'active',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_candidates_org_idx ON qhr_candidates(org_id,full_name);
CREATE TABLE qhr_applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,candidate_id uuid NOT NULL REFERENCES qhr_candidates(id),job_posting_id uuid NOT NULL REFERENCES qhr_job_postings(id),stage varchar(40) NOT NULL DEFAULT 'applied',rejection_reason text,rejected_stage varchar(40),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_applications_org_idx ON qhr_applications(org_id,stage);
CREATE TABLE qhr_interview_rounds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,application_id uuid NOT NULL REFERENCES qhr_applications(id),round_no int NOT NULL,type varchar(40) NOT NULL,interviewer_id uuid,score numeric(6,2),evaluation_note text,scheduled_at timestamptz,status varchar(40) NOT NULL DEFAULT 'scheduled',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_interview_rounds_org_idx ON qhr_interview_rounds(org_id,application_id);
CREATE TABLE qhr_candidate_test_results (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,application_id uuid NOT NULL REFERENCES qhr_applications(id),test_name varchar(160) NOT NULL,score numeric(6,2),result varchar(40) NOT NULL DEFAULT 'pending',note text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_candidate_test_results_org_idx ON qhr_candidate_test_results(org_id,application_id);
CREATE TABLE qhr_job_offers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,application_id uuid NOT NULL REFERENCES qhr_applications(id),salary_offer numeric(20,2),benefits_note text,status varchar(40) NOT NULL DEFAULT 'negotiating',sent_at timestamptz,accepted_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_job_offers_org_idx ON qhr_job_offers(org_id,status);
CREATE TABLE qhr_recruitment_summary_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,plan_id uuid,hired_count int NOT NULL DEFAULT 0,cost numeric(20,2) NOT NULL DEFAULT 0,effectiveness_note text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_recruitment_summary_reports_org_idx ON qhr_recruitment_summary_reports(org_id,plan_id);
CREATE TABLE qhr_probation_periods (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,employee_id uuid NOT NULL,candidate_id uuid,start_date date NOT NULL,end_date date NOT NULL,duration_months int NOT NULL DEFAULT 2,kpi_template jsonb NOT NULL DEFAULT '{}',status varchar(40) NOT NULL DEFAULT 'active',extension_count int NOT NULL DEFAULT 0,evaluated_by uuid,evaluated_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_probation_periods_org_idx ON qhr_probation_periods(org_id,status);
CREATE TABLE qhr_probation_kpi_results (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,probation_id uuid NOT NULL REFERENCES qhr_probation_periods(id),kpi_name varchar(160) NOT NULL,target_value numeric(12,2),actual_value numeric(12,2),achievement_pct numeric(6,2) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_probation_kpi_results_org_idx ON qhr_probation_kpi_results(org_id,probation_id);
CREATE TABLE qhr_probation_extension_requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,probation_id uuid NOT NULL REFERENCES qhr_probation_periods(id),reason text,requested_days int NOT NULL,manager_opinion text,status varchar(40) NOT NULL DEFAULT 'pending',workflow_instance_id uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_probation_extension_requests_org_idx ON qhr_probation_extension_requests(org_id,status);
CREATE TABLE qhr_employee_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,employee_id uuid,candidate_id uuid,doc_type varchar(80) NOT NULL,is_original boolean NOT NULL DEFAULT false,received_at timestamptz,status varchar(40) NOT NULL DEFAULT 'pending',created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_employee_documents_org_idx ON qhr_employee_documents(org_id,employee_id);
CREATE TABLE qhr_onboarding_checklists (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL,candidate_id uuid,employee_id uuid,item varchar(120) NOT NULL,status varchar(40) NOT NULL DEFAULT 'pending',done_by uuid,done_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX qhr_onboarding_checklists_org_idx ON qhr_onboarding_checklists(org_id,candidate_id);
